function parseAmount(s){
  s=String(s).trim();
  var m=s.match(/[¥$]?\s*([0-9][0-9,]*(\.[0-9]+)?)/);
  if(!m) return null;
  return Math.round(parseFloat(m[1].replace(/,/g,''))*100)/100;
}
var CATS=[
  ['餐饮',/餐|饭|食|咖啡|茶|饮|外卖|小吃|早点|夜宵|奶茶|酒水|饮酒|红酒|白酒|啤酒|料酒|鸡尾酒/],
  ['交通',/车|地铁|公交|出租|打车|高铁|火车|机票|油|停车|uber|滴滴|航班|船/],
  ['住宿',/酒店|住宿|民宿|宾馆|旅馆|客栈|青旅/],
  ['购物',/买|购|商城|超市|衣服|鞋|数码|家电|百货|网购|服饰/],
  ['娱乐',/电影|游|票|游戏|健身|书|演出|展览|乐园|景点|唱/],
  ['医疗',/药|医|诊|保健|疫苗|体检|牙/]
];
function categorize(note){
  note=String(note||'');
  for(var i=0;i<CATS.length;i++){ if(CATS[i][1].test(note)) return CATS[i][0]; }
  return '其他';
}
function parseExpenses(text){
  text=String(text||'');
  var lines=text.split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;});
  var items=[], errors=[];
  lines.forEach(function(line,idx){
    var amt=parseAmount(line);
    if(amt==null){ errors.push('第'+(idx+1)+'行未识别金额：'+line); return; }
    var note=line.replace(/^[¥$]?\s*[0-9][0-9,]*(\.[0-9]+)?/,'').trim();
    note=note.replace(/^[\s\-–—:：|丨]+/,'').trim();
    items.push({amount:amt, category:categorize(note), note:note||'未注明', raw:line});
  });
  return {items:items, errors:errors};
}
function summarize(text){
  var p=parseExpenses(text);
  var total=0, byCat={};
  p.items.forEach(function(it){ total+=it.amount; byCat[it.category]=(byCat[it.category]||0)+it.amount; });
  total=Math.round(total*100)/100;
  var lines=['# 报销报告','', '合计：**¥'+total.toFixed(2)+'**（'+p.items.length+' 笔）',''];
  lines.push('## 分类汇总','| 类别 | 金额 | 占比 |','|------|------|------|');
  Object.keys(byCat).sort(function(a,b){return byCat[b]-byCat[a];}).forEach(function(c){
    var s=Math.round(byCat[c]*100)/100;
    var pct= total>0? Math.round(s/total*1000)/10 : 0;
    lines.push('| '+c+' | ¥'+s.toFixed(2)+' | '+pct+'% |');
  });
  lines.push('','## 明细');
  p.items.forEach(function(it,i){ lines.push((i+1)+'. ['+it.category+'] '+it.note+' — ¥'+it.amount.toFixed(2)); });
  if(p.errors.length) lines.push('','> 跳过 '+p.errors.length+' 行无法识别金额');
  return {total:total, count:p.items.length, byCategory:byCat, report:lines.join('\n'), errors:p.errors};
}
var EXPORTS={parseAmount:parseAmount, categorize:categorize, parseExpenses:parseExpenses, summarize:summarize};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ExpenseReportForgePure = EXPORTS; }
